import * as THREE from 'three';
import { SVGLoader } from 'three/examples/jsm/loaders/SVGLoader.js';

const HEADER_TEMPLATE = ({ units, feedRate, spindleSpeed, laserPower }) => `;-----------------------------------------------------
; CNC Router / Laser Preview G-Code
; Units: ${units}
; Feed Rate: ${feedRate} mm/min
; Spindle/Laser: ${spindleSpeed || laserPower}
; Generated by CNCRouterLaserApp
;-----------------------------------------------------
G21 ; Set units to millimeters
G90 ; Absolute positioning
G94 ; Feed per minute
${laserPower ? `M4 S${laserPower} ; Enable laser` : ''}
G0 Z5.00 F3000 ; Safe travel height
`;

export function generateGcodeForRaster({ imageData, cols, rows, widthMm, heightMm, maxDepthMm, feedRate, laserMode, laserPower }) {
  const xStep = widthMm / (cols - 1);
  const yStep = heightMm / (rows - 1);
  const lines = [HEADER_TEMPLATE({ units: 'mm', feedRate, spindleSpeed: null, laserPower: laserMode ? laserPower : null })];

  for (let row = 0; row < rows; row += 1) {
    const y = row * yStep;
    const rowDirection = row % 2 === 0 ? 1 : -1;
    const startX = rowDirection === 1 ? 0 : widthMm;

    lines.push(`; Line ${row + 1} / ${rows}`);
    lines.push(`G0 X${startX.toFixed(2)} Y${y.toFixed(2)} Z5.00`);

    for (let col = 0; col < cols; col += 1) {
      const actualCol = rowDirection === 1 ? col : cols - 1 - col;
      const idx = actualCol * 4 + row * cols * 4;
      const brightness = (0.299 * imageData[idx] + 0.587 * imageData[idx + 1] + 0.114 * imageData[idx + 2]) / 255;
      const zValue = laserMode ? 0.0 : (1 - brightness) * maxDepthMm;
      const powerValue = laserMode ? Math.round(laserPower * (1 - brightness)) : null;
      const x = actualCol * xStep;

      if (laserMode) {
        lines.push(`M3 S${powerValue}`);
        lines.push(`G1 X${x.toFixed(2)} Y${y.toFixed(2)} F${feedRate}`);
      } else {
        lines.push(`G1 X${x.toFixed(2)} Y${y.toFixed(2)} Z${zValue.toFixed(3)} F${feedRate}`);
      }
    }
  }

  lines.push('G0 Z5.00 F3000 ; Retract to safe height');
  if (laserMode) lines.push('M5 ; Turn laser off');
  lines.push('G0 X0 Y0 ; Home position');
  lines.push('M30 ; End of program');
  return lines.join('\n');
}

export function generateGcodeForSVG(svgText, { widthMm, feedRate, cutDepth, retractHeight, spindleSpeed }) {
  const svgData = new SVGLoader().parse(svgText);
  const shapes = [];
  svgData.paths.forEach((path) => {
    const createdShapes = SVGLoader.createShapes(path);
    createdShapes.forEach((shape) => shapes.push(shape));
  });

  const bounds = findShapeBounds(shapes);
  const scale = widthMm / Math.max(bounds.width, bounds.height);
  const offsetX = -bounds.minX * scale;
  const offsetY = -bounds.minY * scale;

  const lines = [
    ';-----------------------------------------------------',
    '; SVG Cut Path G-Code',
    `; Material width: ${widthMm.toFixed(1)} mm`,
    `; Cut depth: ${cutDepth.toFixed(1)} mm`,
    ';-----------------------------------------------------',
    'G21',
    'G90',
    'G94',
    `M3 S${spindleSpeed} ; Spindle on`,
    `G0 Z${retractHeight.toFixed(2)} F3000`,
    'G0 X0 Y0'
  ];

  shapes.forEach((shape, index) => {
    const points = shape.extractPoints(64).shape;
    if (!points.length) return;

    const first = mapPoint(points[0], scale, offsetX, offsetY);
    lines.push(`; Shape ${index + 1}`);
    lines.push(`G0 X${first.x.toFixed(2)} Y${first.y.toFixed(2)} F3000`);
    lines.push(`G1 Z${(-cutDepth).toFixed(2)} F1200`);

    points.forEach((point) => {
      const mapped = mapPoint(point, scale, offsetX, offsetY);
      lines.push(`G1 X${mapped.x.toFixed(2)} Y${mapped.y.toFixed(2)} F${feedRate}`);
    });

    lines.push(`G1 X${first.x.toFixed(2)} Y${first.y.toFixed(2)} F${feedRate}`);
    lines.push(`G0 Z${retractHeight.toFixed(2)} F3000`);
  });

  lines.push('M5 ; Spindle off');
  lines.push('G0 X0 Y0');
  lines.push('M30');
  return lines.join('\n');
}

function findShapeBounds(shapes) {
  const box = new THREE.Box2();
  shapes.forEach((shape) => {
    const points = shape.extractPoints(64).shape;
    points.forEach((point) => box.expandByPoint(new THREE.Vector2(point.x, point.y)));
  });
  return {
    minX: box.min.x,
    minY: box.min.y,
    width: box.max.x - box.min.x,
    height: box.max.y - box.min.y
  };
}

function mapPoint(point, scale, offsetX, offsetY) {
  return {
    x: point.x * scale + offsetX,
    y: point.y * scale + offsetY
  };
}
